        .messages-search-icon {
            position: absolute;
            left: 25px;
            top: 19px; /* Adjust if search bar padding changes */
            color: var(--light-text);
            font-size: 16px;
        }

        .conversation-list-item { 
            display: flex; 
            align-items: center; 
            padding: 12px 15px; 
            border-bottom: 1px solid var(--border-color); 
            cursor: pointer; 
            transition: all var(--transition-medium) ease; 
            background-color: var(--message-conversation-bg); 
            position: relative;
            overflow: hidden;
            gap: 12px;
            flex-shrink: 0; /* Prevent items from shrinking */
