        .conversation-list-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 3px;
            height: 100%;
            background: var(--primary-color);
            opacity: 0;
            transition: all var(--transition-quick) ease;
        }

        .conversation-list-item:hover { 
            transform: translateX(3px);
        }

        .conversation-list-item:hover::before {
            opacity: 1;
        }

        .conversation-list-item:active {
            transform: translateX(5px);
        }

        .conversation-list-item:last-child { 
            border-bottom: none; 
        }

        .conversation-avatar {
            width: 45px;
            height: 45px;
            border-radius: 50%;
