            border: 2px solid var(--card-bg);
            display: none;
        }

        .conversation-online-status.online {
            display: block;
        }

        .conversation-list-details { 
            flex-grow: 1; 
            overflow: hidden; /* Prevent text overflow issues */
        }

        .conversation-list-title { 
            font-weight: bold;
            color: var(--primary-color);
            font-size: 16px;
            display: block;
            margin-bottom: 4px;
            transition: color var(--transition-medium) ease;
            display: flex;
            align-items: center;
            gap: 5px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .conversation-list-verified {
