        @keyframes pulseUnread {
            0% { transform: scale(1); box-shadow: 0 2px 5px rgba(239, 83, 80, 0.3); }
            50% { transform: scale(1.1); box-shadow: 0 2px 8px rgba(239, 83, 80, 0.5); }
            100% { transform: scale(1); box-shadow: 0 2px 5px rgba(239, 83, 80, 0.3); }
        }

        .conversation-list-status {
            display: flex;
            align-items: center;
            flex-direction: column;
            padding-left: 5px;
        }

        #detailed-message-view { 
            display: none; /* Initially hidden */
