        .detailed-view-user-info {
            display: flex;
            flex-direction: column;
            flex-grow: 1;
            overflow: hidden; /* Prevent title from pushing actions out */
        }

        #detailed-view-title { 
            font-weight: bold; 
            color: var(--primary-color); 
            font-size: 16px; 
            transition: color var(--transition-medium) ease;
            display: flex;
            align-items: center;
            gap: 5px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .detailed-view-status {
            font-size: 12px;
            color: var(--light-text);
