        }

        .detailed-view-actions {
            display: flex;
            gap: 8px;
            flex-shrink: 0; /* Prevent actions from shrinking */
        }

        .detailed-view-action {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--primary-color);
            background-color: rgba(var(--primary-color-rgb), 0.1);
