        }

        .chat-input-mock {
            display: flex;
            align-items: center;
            padding: 10px 15px;
            background-color: var(--card-bg);
            border-top: 1px solid var(--border-color);
            position: sticky; /* Stick to bottom of #detailed-message-view */
            bottom: 0;
            transition: all var(--transition-medium) ease;
            flex-shrink: 0; /* Fixed height */
        }

        .chat-input-field {
            flex-grow: 1;
            padding: 10px 15px;
