            font-style: italic;
            transition: all var(--transition-quick) ease;
        }

        .chat-input-actions {
            display: flex;
            gap: 10px;
            margin-left: 10px;
        }

        .chat-input-action {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            background-color: var(--primary-color);
            color: white;
            cursor: pointer;
            transition: all var(--transition-quick) ease;
            box-shadow: 0 2px 5px rgba(var(--primary-color-rgb), 0.3);
        }

        .chat-input-action:hover {
