        .message-attachment-item, .moment-media-text-item { /* Shared style for clickable media */
            background-color: var(--message-attachment-bg); 
            border: 1px solid var(--message-attachment-border);
            color: var(--primary-color); 
            padding: 8px 12px; 
            border-radius: 6px; 
            font-size: 13px;
            margin-bottom: 6px; 
            display: flex; 
            align-items: center; 
            gap: 6px; 
            cursor: pointer;
            transition: all var(--transition-quick) ease;
            position: relative;
            overflow: hidden;
        }

        .message-attachment-item::before, .moment-media-text-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: var(--primary-color);
            opacity: 0;
            transition: opacity var(--transition-quick) ease;
            z-index: 0;
        }

        .message-attachment-item:hover, .moment-media-text-item:hover { 
