        .message-attachment-item span, .moment-media-text-item span {
            position: relative;
            z-index: 1;
        }

        /* START: CSS Changes for Moments Scrolling */
        .phone-app-content[data-app="moments"] { 
            background-color: var(--moments-panel-bg-color);
            height: 100%; /* Takes full height of its container in phone-screen */
            width: 100%;
            display: flex;
            flex-direction: column;
            overflow: hidden; /* Clips anything outside this app's boundary */
        }

        #moments-content { 
            /* background-color can be inherited or var(--moments-panel-bg-color) if needed */
            display: flex;
            flex-direction: column;
            flex-grow: 1;   /* Takes remaining vertical space after .app-header */
            min-height: 0;  /* Crucial for allowing children to scroll within a flex item */
            overflow: hidden; /* This is fine, as .moments-container inside it will handle scrolling */
        }
        /* END: CSS Changes for Moments Scrolling */

        /* Moments pagination controls */
        .moments-pagination {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 20px;
            /* margin-bottom: 20px; Removed, spacing handled by .moments-container padding */
