            background: rgba(255, 255, 255, 0.5);
            border-radius: 10px;
            border: 1px solid var(--border-color);
            box-shadow: var(--shadow);
            transition: background-color var(--transition-medium) ease;
            flex-shrink: 0; /* Prevent pagination from shrinking */
            margin: 0 15px 15px 15px; /* Add some horizontal and bottom margin */
        }

        .dark .moments-pagination {
            background: rgba(42, 36, 31, 0.5);
        }

        .moment-nav-button {
            padding: 8px 16px;
            background-color: var(--primary-color);
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            font-family: inherit;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 8px;
            transition: all var(--transition-quick) ease;
            box-shadow: 0 2px 5px rgba(var(--primary-color-rgb), 0.3);
        }

        .moment-nav-button:hover:not(:disabled) {
            transform: translateY(-2px);
            box-shadow: 0 4px 8px rgba(var(--primary-color-rgb), 0.4);
        }

        .moment-nav-button:disabled {
            background-color: rgba(var(--primary-color-rgb), 0.3);
            cursor: not-allowed;
            box-shadow: none;
        }

        #moment-counter {
            font-size: 14px;
            font-weight: bold;
            color: var(--primary-color);
            min-width: 60px;
            text-align: center;
