        .moments-container { 
            display: flex; 
            flex-direction: column; 
            gap: 20px; /* Adjusted gap slightly */
            flex-grow: 1; /* Takes available space within #moments-content after pagination */
            overflow-y: auto; /* Enables vertical scrolling if content exceeds its bounds */
            min-height: 0; /* Good practice for scrollable flex children */
            padding: 0 15px 15px 15px; /* Padding for content spacing and scrollbar */
        }

        .moment-post { 
            background: rgba(255, 255, 255, 0.9); 
            border: 1px solid var(--border-color); 
            border-radius: 10px; 
            overflow: hidden; 
            box-shadow: var(--shadow);
            transition: all var(--transition-medium) ease;
            display: none; /* Hide all posts by default */
            flex-shrink: 0; /* Prevent posts from shrinking weirdly if container is too small */
        }

        .moment-post.active {
            display: block; /* Only show active post */
            animation: fadeInPost 0.5s ease;
        }

        @keyframes fadeInPost {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .dark .moment-post {
            background: rgba(42, 36, 31, 0.8);
        }

        .moment-post:hover {
            transform: translateY(-3px);
            box-shadow: var(--shadow-hover);
        }

        .moment-post-header { 
