        }

        .dark .moment-post-header {
            background: rgba(219, 180, 138, 0.05);
        }

        .moment-avatar { 
            width: 48px; 
            height: 48px; 
            border-radius: 50%; 
            margin-right: 15px; 
            border: 2px solid var(--accent-color); 
