            overflow: hidden; /* Prevent author/timestamp from overflowing */
        }

        .moment-author { 
            font-weight: bold; 
            color: var(--primary-color); 
            font-size: 17px; 
            margin-bottom: 5px;
            transition: color var(--transition-medium) ease;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .moment-timestamp { 
