        /* App Grid Area (visible when no app is active) */
        .phone-app-grid-area {
            padding: 15px;
            overflow-y: auto; /* Scroll for app icons if many */
            flex-grow: 1;
            min-height: 0;
        }

        /* 手机应用内容区域 */
        .phone-app-content {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            /* background-color: var(--bg-color); Set by specific app styles */
            z-index: 20;
            display: none; /* Base: hidden */
            flex-direction: column;
            overflow: hidden; /* Important: each app manages its own internal scroll */
        }

        .phone-app-content.active {
            display: flex; /* Active: shown */
            animation: fadeIn 0.3s forwards;
        }

        /* 应用标题栏 */
        .app-header {
            /* position: sticky; Not needed if parent manages scroll */
            /* top: 0; */
            background-color: var(--card-bg);
            border-bottom: 1px solid var(--border-color);
            padding: 10px 15px;
            display: flex;
            align-items: center;
            z-index: 5; /* Above content within app */
            transition: all var(--transition-medium) ease;
            /* margin-bottom: 15px; Spacing handled by content area padding */
            flex-shrink: 0; /* Fixed height */
            backdrop-filter: blur(5px);
        }

        .app-back-button {
            background: none;
            border: none;
            font-size: 18px;
            color: var(--primary-color);
            cursor: pointer;
            margin-right: 15px;
            padding: 8px;
            transition: all var(--transition-quick) ease;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            width: 36px;
            height: 36px;
            background-color: rgba(var(--primary-color-rgb), 0.1);
        }

        .app-back-button:hover {
            color: #fff;
            background-color: var(--primary-color);
            transform: translateX(-3px);
        }

        .app-title {
            font-weight: bold;
            color: var(--primary-color);
            font-size: 16px;
            flex-grow: 1;
            text-align: center;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        /* 手机底部导航栏 */
        .phone-nav-bar {
            height: 20px;
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: var(--primary-color);
            gap: 20px;
            flex-shrink: 0; /* Fixed height */
        }

        .phone-nav-item {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background-color: rgba(255, 255, 255, 0.5);
            transition: all var(--transition-quick) ease;
        }

        .phone-nav-item:hover {
            background-color: rgba(255, 255, 255, 0.8);
            transform: scale(1.2);
        }

        /* APP网格布局 */
        .app-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(var(--app-icon-size, 64px), 1fr)); /* More responsive */
            gap: 20px;
            margin-top: 20px; /* Spacing from "My Phone" title */
        }

        /* APP图标样式 */
        .app-icon {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            cursor: pointer;
            transition: all var(--transition-medium) ease;
            padding: 5px; /* Add some padding for touch targets */
        }

        .app-icon:hover {
            transform: translateY(-5px) scale(1.05);
        }

        .app-icon:active {
            transform: translateY(2px) scale(0.95);
        }

        .app-icon-image {
            width: var(--app-icon-size);
            height: var(--app-icon-size);
            border-radius: var(--app-icon-radius);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: calc(var(--app-icon-size) * 0.45); /* Icon size relative to container */
            color: white;
            box-shadow: 0 5px 15px rgba(0,0,0,0.1);
            position: relative;
            overflow: hidden;
        }

        .app-icon-image::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(135deg, rgba(255,255,255,0.2), transparent 50%);
            z-index: 1;
        }

        .app-icon-name {
            font-size: 14px;
            color: var(--text-color);
            font-weight: 500;
            text-align: center;
            width: 100%; /* Ensure text wraps if too long */
            overflow-wrap: break-word;
        }

        /* 特定APP图标样式 */
        .app-icon[data-app="messages"] .app-icon-image {
            background: linear-gradient(45deg, #1E88E5, #64B5F6);
        }

        .app-icon[data-app="moments"] .app-icon-image {
            background: linear-gradient(45deg, #43A047, #81C784);
        }

        .app-icon[data-app="settings"] .app-icon-image {
            background: linear-gradient(45deg, #757575, #BDBDBD);
        }

        /* APP通知指示器 */
        .app-notification {
            position: absolute;
            top: -5px;
            right: -5px;
            background-color: var(--status-danger);
            color: white;
            border-radius: 50%;
            min-width: 20px; /* Use min-width for single digit numbers */
            height: 20px;
            padding: 0 4px; /* Add horizontal padding for multi-digit numbers */
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            font-weight: bold;
            box-shadow: 0 2px 5px rgba(239, 83, 80, 0.5);
            animation: pulseAppNotification 2s infinite;
            z-index: 2;
        }

        @keyframes pulseAppNotification {
            0% { transform: scale(1); }
            50% { transform: scale(1.2); }
            100% { transform: scale(1); }
        }

        @media (max-width: 768px) {
            .container { padding: 0 !important; }

            .menu-bar { 
                flex-direction: column; 
                align-items: stretch; 
                padding: 0; 
                border-radius: 0; 
            }

            .logo { 
                font-size: 24px; 
                padding: 12px 0; 
                text-align: center; 
                background: rgba(255,255,255,0.9); 
                border-bottom: 1px solid var(--border-color);
                animation: none;
            }

            .dark .logo {
                background: rgba(42,36,31,0.9);
            }

            .menu-items { 
                flex-direction: row; 
                justify-content: space-around; 
                background: rgba(255,255,255,0.95); 
                border-bottom: 1px solid var(--border-color);
            }

            .dark .menu-items {
                background: rgba(42,36,31,0.95);
            }

            .menu-item { 
                flex: 1; 
                text-align: center; 
                font-size: 15px; 
                padding: 12px 5px; 
                border-radius: 0; 
                box-shadow: none;
            }

            .panel { padding: 15px !important; }
            .panel-title { font-size: 22px !important; margin-bottom: 20px; }

            .conversation-list-item { padding: 10px 12px; gap: 10px; }
            .conversation-avatar { width: 40px; height: 40px; font-size: 16px; }
            .conversation-list-title { font-size: 15px; }
            .conversation-list-preview { font-size: 12px; }
            .conversation-list-time { font-size: 10px; }
