                                author: tempComments[num].author, 
                                text: tempComments[num].text 
                            }); 
                        } 
                    }

                    post.mediaText.sort((a, b) => a.index - b.index);
                    if (post.author) { allPosts.push(post); }
                });
                return allPosts;
            }
        };

