                document.body.style.fontSize = `${settings.fontSize}px`; 
                document.documentElement.style.setProperty('--bg-color', settings.bgColor); 
                document.documentElement.style.setProperty('--primary-color', settings.primaryColor); 
                document.documentElement.style.setProperty('--content-bg-alpha', parseFloat(settings.contentBrightness) / 100); 

                const fontSizeValueEl = $('#font-size-value'); 
                if (fontSizeValueEl) fontSizeValueEl.textContent = `${settings.fontSize}px`; 

                const brightnessValueEl = $('#brightness-value'); 
                if (brightnessValueEl) brightnessValueEl.textContent = `${settings.contentBrightness}%`; 

                if (settings.primaryColor) {
                    const hexToRgb = (hex) => {
                        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                        return result ? {
                            r: parseInt(result[1], 16),
                            g: parseInt(result[2], 16),
                            b: parseInt(result[3], 16)
                        } : null;
                    };
                    const rgb = hexToRgb(settings.primaryColor);
                    if (rgb) {
                        document.documentElement.style.setProperty('--primary-color-rgb', `${rgb.r}, ${rgb.g}, ${rgb.b}`);
                    }
                }
            },
            loadSettingsToPanel(settings) { 
                const fontFamilySelect = $('#font-family-setting'); 
                const fontSizeRange = $('#font-size-setting'); 
                const bgColorPicker = $('#bg-color-setting'); 
                const primaryColorPicker = $('#primary-color-setting'); 
