                if (fontSizeRange) fontSizeRange.value = settings.fontSize; 
                if (bgColorPicker) bgColorPicker.value = settings.bgColor; 
                if (primaryColorPicker) primaryColorPicker.value = settings.primaryColor; 
                if (brightnessRange) brightnessRange.value = settings.contentBrightness; 

