        function updatePhoneNotifications(totalUnreadMessages) {
            const phoneDot = $('.phone-dot');
            const phoneMenuItem = $('.menu-item[data-panel="phone"]');

            if (phoneDot && phoneMenuItem) {
                if (totalUnreadMessages > 0 && !phoneMenuItem.classList.contains('active')) {
                    phoneDot.style.display = 'inline-block';
                } else {
                    phoneDot.style.display = 'none';
                }
            }
        }

        function updateAppNotifications() {
            const messagesNotification = $('.messages-app-notification');
            if (messagesNotification) {
                let totalUnread = 0;
                Object.values(allConversationsData).forEach(conv => {
                    totalUnread += parseInt(conv.unreadCount || 0);
                });

                messagesNotification.textContent = totalUnread > 99 ? '99+' : totalUnread;
                messagesNotification.style.display = totalUnread > 0 ? 'flex' : 'none';
            }

            const momentsNotification = $('.moments-app-notification');
            if (momentsNotification && totalMoments > 0) {
                const lastSeenCount = parseInt(localStorage.getItem('tianxiang_moments_last_seen_count') || '0');
                const newMomentsCount = totalMoments - lastSeenCount;

                momentsNotification.textContent = newMomentsCount > 99 ? '99+' : newMomentsCount;
                momentsNotification.style.display = newMomentsCount > 0 ? 'flex' : 'none';
            }
        }

        function showDetailedMessages(convId) {
            const detailedTitle = $('#detailed-view-title');
            const detailedAvatar = $('.detailed-view-avatar');
            const messagesArea = $('.detailed-messages-area');
            const statusText = $('.online-status-text');
            const typingIndicator = $('.detailed-view-typing');
            const convData = allConversationsData[convId];

            if (!convData || !detailedTitle || !detailedAvatar || !messagesArea || !statusText || !typingIndicator) return;

            let detailedHeaderTitle = convId; 
            if (convData.uniqueSenders.size === 1) {
                detailedHeaderTitle = convData.representativeSender || convId;
            } else if (convData.uniqueSenders.size > 1) {
                detailedHeaderTitle = `${convId} (${convData.uniqueSenders.size}人群聊)`;
            }

            detailedTitle.textContent = detailedHeaderTitle;
            detailedAvatar.textContent = (detailedHeaderTitle.charAt(0) || '?').toUpperCase();

            const isOnline = Math.random() > 0.3;
            statusText.style.display = 'inline'; // Default
            typingIndicator.classList.remove('active'); // Default

            if (isOnline) {
                statusText.textContent = '在线';
                statusText.style.color = 'var(--status-good)';
                if (Math.random() > 0.85) { // Lower chance of typing
                    statusText.style.display = 'none';
                    typingIndicator.classList.add('active');
                }
            } else {
                statusText.textContent = `最后在线：${Math.floor(Math.random() * 50) + 10}分钟前`; // More realistic last seen
                statusText.style.color = 'var(--light-text)';
            }

            messagesArea.innerHTML = ''; // Clear previous messages
            const dateGroups = groupMessagesByDate(convData.messages);

            Object.keys(dateGroups).sort().forEach(date => { // Sort dates if they are actual dates
                const dateSeparator = document.createElement('div');
                dateSeparator.className = 'message-date-separator';
                dateSeparator.innerHTML = `<span class="message-date-text">${date}</span>`;
                messagesArea.appendChild(dateSeparator);

                dateGroups[date].forEach(msg => {
                    const entryDiv = document.createElement('div');
                    entryDiv.className = 'message-entry sender-message'; // All are sender-message for now

                    let attachmentsHTML = '';
                    if (msg.images.length > 0 || msg.videos.length > 0) {
                        attachmentsHTML += '<div class="message-attachments">';
                        msg.images.forEach((imgDesc, idx) => {
                            if(imgDesc) attachmentsHTML += `<div class="message-attachment-item" data-media-type="image" data-media-title="图片 ${idx + 1}" data-media-text="${encodeURIComponent(imgDesc || '无详细描述')}"><i class="fas fa-image"></i> <span>图片 ${idx + 1} (点击查看)</span></div>`;
                        });
                        msg.videos.forEach((vidDesc, idx) => {
                            if(vidDesc) attachmentsHTML += `<div class="message-attachment-item" data-media-type="video" data-media-title="视频 ${idx + 1}" data-media-text="${encodeURIComponent(vidDesc || '无详细描述')}"><i class="fas fa-video"></i> <span>视频 ${idx + 1} (点击查看)</span></div>`;
                        });
                        attachmentsHTML += '</div>';
                    }

                    entryDiv.innerHTML = `
                        <div class="message-entry-header">
                            <div class="message-sender-wrapper">
                                <span class="message-sender">${msg.sender || '未知'}</span>
                            </div>
                            <span class="message-timestamp">${formatTime(msg.timestamp) || '（未知时间）'}</span>
                        </div>
                        <div class="message-content-body">${msg.content ? msg.content.replace(/\n/g, '<br>') : '（无内容）'}</div>
                        ${attachmentsHTML}`; 
                    messagesArea.appendChild(entryDiv);
                });
            });

            messagesArea.scrollTop = messagesArea.scrollHeight; // Scroll to bottom
            switchToDetailedView();

            // Mark messages as read for this conversation
            if (convData.unreadCount && parseInt(convData.unreadCount) > 0) {
                convData.unreadCount = '0';
                renderConversationList(); // Re-render list to update unread count display
                updateAppNotifications(); // Update main app notification
            }
        }

        function formatTime(timestamp) {
            if (!timestamp) return '';
            // Basic time formatting, can be expanded (e.g., using Date objects if timestamps are ISO strings)
            if (timestamp.match(/^\d{2}:\d{2}$/)) return timestamp; // Already HH:MM
            // Add more sophisticated date/time parsing if needed
            return timestamp; 
        }

        function groupMessagesByDate(messages) {
            const groups = {};
            messages.forEach(msg => {
                let dateString = '今天'; 
                // This is a placeholder for actual date parsing and grouping logic
                // For a real app, you'd parse msg.timestamp (if it's a full date)
                // and group by "Today", "Yesterday", "YYYY-MM-DD", etc.
                if (msg.timestamp) {
                    const random = Math.random();
                    if (random < 0.3) dateString = '今天'; // Higher chance for 'Today' for demo
                    else if (random < 0.6) dateString = '昨天';
                    else if (random < 0.8) dateString = '本周';
                    else dateString = '更早';
                }
                if (!groups[dateString]) groups[dateString] = [];
                groups[dateString].push(msg);
            });
            return groups;
        }

        function switchToListView() {
            const listView = $('#conversation-list-view');
            const detailedView = $('#detailed-message-view');
