            if (listView && detailedView && messagesContent) {
                listView.style.display = 'flex'; // It's a flex column
                detailedView.style.display = 'none';
                // Ensure the search bar is visible if it was hidden
                const searchBar = listView.querySelector('.messages-search-bar');
                if(searchBar) searchBar.style.display = 'block';
            }
        }

        function switchToDetailedView() {
            const listView = $('#conversation-list-view');
