        function handleMomentNavigation() {
            const prevButton = $('#prev-moment');
            const nextButton = $('#next-moment');

            if (!prevButton || !nextButton) return;

            prevButton.addEventListener('click', () => navigateToMoment(currentMomentIndex - 1));
            nextButton.addEventListener('click', () => navigateToMoment(currentMomentIndex + 1));
        }

        function navigateToMoment(index) {
            const momentContainer = $('.moments-container');
            const prevButton = $('#prev-moment');
            const nextButton = $('#next-moment');
            const momentCounter = $('#moment-counter');

            if (!momentContainer || !prevButton || !nextButton || !momentCounter || index < 0 || index >= totalMoments) return;

            const currentActivePost = momentContainer.querySelector('.moment-post.active');
            if (currentActivePost) currentActivePost.classList.remove('active');

            const newActivePost = momentContainer.querySelector(`.moment-post[data-post-id="post-${index}"]`);
            if (newActivePost) {
                newActivePost.classList.add('active');
                currentMomentIndex = index;
                momentCounter.textContent = `${index + 1} / ${totalMoments}`;
                prevButton.disabled = index === 0;
                nextButton.disabled = index === totalMoments - 1;
            }
        }

        function handlePanelSwitching() {
            const menuItems = $$('.menu-item');
            const panels = $$('.panel');
            const phoneAppGridArea = $('.phone-app-grid-area'); // The area showing app icons

            menuItems.forEach(item => {
                item.addEventListener('click', function() {
                    const targetPanelId = this.dataset.panel;
                    menuItems.forEach(i => i.classList.remove('active'));
                    this.classList.add('active');

                    panels.forEach(p => {
                        const isActivePanel = p.id === targetPanelId;
                        p.classList.toggle('active', isActivePanel);
                        p.style.display = isActivePanel ? (p.id === 'phone' ? 'flex' : 'block') : 'none';

                        if (isActivePanel && targetPanelId === 'phone') {
                            const phoneDot = $('.phone-dot');
                            if (phoneDot) phoneDot.style.display = 'none';

                            // Show app grid, hide all apps
                            if(phoneAppGridArea) phoneAppGridArea.style.display = 'block';
                            $$('.phone-app-content').forEach(appContent => {
                                appContent.classList.remove('active');
                                appContent.style.display = 'none'; 
                            });
                            updatePhoneTime();
                        }
                    });
                });
            });

            // Initial setup
            const initialActiveMenuItem = $('.menu-item.active');
            if (initialActiveMenuItem) {
                initialActiveMenuItem.click(); // Simulate click to set up correctly
            } else if (menuItems.length > 0) {
                menuItems[0].click(); // Activate the first item if none are active
            }
        }

        function updatePhoneTime() {
            const timeEl = $('#phone-time');
            if (timeEl) {
                const now = new Date();
                const hours = now.getHours().toString().padStart(2, '0');
                const minutes = now.getMinutes().toString().padStart(2, '0');
                timeEl.textContent = `${hours}:${minutes}`;
            }
        }

        function handleAppIconClicks() {
            const appIcons = $$('.app-icon');
            const phoneAppGridArea = $('.phone-app-grid-area');
            if (!appIcons.length) return;

            appIcons.forEach(icon => {
                icon.addEventListener('click', () => {
                    const appId = icon.dataset.app;
                    const appContentTarget = $(`.phone-app-content[data-app="${appId}"]`);

                    if (appContentTarget) {
                        // Hide app grid
                        if(phoneAppGridArea) phoneAppGridArea.style.display = 'none';

                        // Hide other apps
                        $$('.phone-app-content').forEach(content => {
                            if (content !== appContentTarget) {
                                content.classList.remove('active');
                                content.style.display = 'none';
                            }
                        });

                        // Show current app
                        appContentTarget.classList.add('active');
                        appContentTarget.style.display = 'flex'; 

                        // Clear notifications and specific app states
                        if (appId === 'messages') {
                            const notif = $('.messages-app-notification');
                            if (notif) notif.style.display = 'none';
                            // If opening messages, ensure it's in list view if no conversation was active
                            // Or, if a conversation was active, it should remain. This logic is handled by showDetailedMessages.
                            // For now, simply ensure list view is primary if no detailed view is active.
                             if (!$('#detailed-message-view').style.display || $('#detailed-message-view').style.display === 'none') {
                                switchToListView();
                            }
                        } else if (appId === 'moments') {
                            const notif = $('.moments-app-notification');
                            if (notif) notif.style.display = 'none';
                            localStorage.setItem('tianxiang_moments_last_seen_count', totalMoments.toString());
                            // Ensure the first moment is active if navigating from app grid
                            if (totalMoments > 0) navigateToMoment(0);
                        }
                    }
                });
            });
        }

        function handlePhoneAppBackButtons() {
            const phoneAppGridArea = $('.phone-app-grid-area');
            $$('.phone-app-content .app-back-button').forEach(btn => {
                btn.addEventListener('click', () => {
                    const app = btn.closest('.phone-app-content');
                    if (app) {
                        app.classList.remove('active');
                        app.style.display = 'none'; 
                    }
                    // Show app grid
                    if(phoneAppGridArea) phoneAppGridArea.style.display = 'block'; 
                });
            });

            // Special back button for detailed message view
            const backToListBtn = $('#back-to-list-btn');
            if(backToListBtn) {
                backToListBtn.addEventListener('click', switchToListView);
            }
        }

        function handlePlayerChoiceClick() { const choicesContainer = $('.player-choices'); if (!choicesContainer) return; choicesContainer.addEventListener('click', function(event) { const choiceOption = event.target.closest('.choice-option'); if (choiceOption && !choiceOption.classList.contains('disabled')) { const choiceText = choiceOption.querySelector('.choice-text').textContent.trim(); const messageToSend = `{{user}}决定 ${choiceText}`; try { const stInput = window.parent.document.querySelector('#send_textarea, #chat_input textarea, #user_input'); const stSendButton = window.parent.document.querySelector('#send_but, #send_button, #submit_button'); if (stInput && stSendButton) { stInput.value = messageToSend; stInput.dispatchEvent(new Event('input', { bubbles: true })); stSendButton.click(); } else { throw new Error('SillyTavern input or send button not found.'); } } catch (e) { navigator.clipboard.writeText(messageToSend).then(() => { console.warn(`无法直接发送指令，已将内容复制到剪贴板：\n${messageToSend}`); }).catch(err => { console.error(`无法发送指令或复制到剪贴板。\n请手动复制：${messageToSend}`); }); } } }); }
        function handleSettingsChanges() { const settingsInputs = { fontFamily: $('#font-family-setting'), fontSize: $('#font-size-setting'), bgColor: $('#bg-color-setting'), primaryColor: $('#primary-color-setting'), contentBrightness: $('#brightness-setting'), resetBtn: $('#reset-settings-btn') }; const currentSettings = loadSettings(); UIUpdater.loadSettingsToPanel(currentSettings); Object.keys(settingsInputs).forEach(key => { if (key === 'resetBtn' || !settingsInputs[key]) return; settingsInputs[key].addEventListener('input', () => { currentSettings[key] = settingsInputs[key].value; UIUpdater.applySettings(currentSettings); saveSettings(currentSettings); }); }); if(settingsInputs.resetBtn) { settingsInputs.resetBtn.addEventListener('click', () => { localStorage.removeItem('tianxiang_settings'); UIUpdater.loadSettingsToPanel(defaultSettings); saveSettings(defaultSettings); }); } }
        function saveSettings(settings) { localStorage.setItem('tianxiang_settings', JSON.stringify(settings)); }
        function loadSettings() { const saved = localStorage.getItem('tianxiang_settings'); if (saved) { try { const parsed = JSON.parse(saved); const allKeysPresent = Object.keys(defaultSettings).every(key => key in parsed); if (allKeysPresent) return parsed; else { return { ...defaultSettings, ...parsed }; } } catch (e) { return { ...defaultSettings }; } } return { ...defaultSettings }; }
        function handleMomentsInteractions() { const momentsContainer = $('.moments-container'); if (momentsContainer) { momentsContainer.addEventListener('click', function(event) { const likeButton = event.target.closest('.like-action'); if (likeButton) { const icon = likeButton.querySelector('i'); const countSpan = likeButton.querySelector('.action-count'); let count = parseInt(countSpan.textContent) || 0; const isLiked = likeButton.dataset.liked === 'true'; if (isLiked) { icon.classList.remove('fas'); icon.classList.add('far'); likeButton.classList.remove('liked'); count = Math.max(0, count - 1); likeButton.dataset.liked = 'false'; } else { icon.classList.remove('far'); icon.classList.add('fas'); likeButton.classList.add('liked'); count++; likeButton.dataset.liked = 'true'; } countSpan.textContent = count; } }); } }

        function processInjectedText(rawText) {
            if (typeof rawText !== 'string' || !rawText.trim()) { console.warn("Received empty or invalid data."); UIUpdater.updateMainContent(null); UIUpdater.updateOptions([]); UIUpdater.updateMessagesPanel([]); UIUpdater.updateMomentsData([]); return; }
            let gameContent = rawText;
            const gameTextMatch = rawText.match(/<gametext>([\s\S]*?)<\/gametext>/i);
            if (gameTextMatch && gameTextMatch[1]) { gameContent = gameTextMatch[1]; }
            else { const overallMatch = rawText.match(/<overall>([\s\S]*?)<\/overall>/i); if (overallMatch && overallMatch[1]) { gameContent = overallMatch[1]; } }

            const mainData = DataExtractor.extractMainContent(gameContent);
            const optionsData = DataExtractor.extractOptions(gameContent);
            const chatData = DataExtractor.extractChatData(gameContent);
            const momentsData = DataExtractor.extractMomentsData(gameContent);

            UIUpdater.updateMainContent(mainData);
            UIUpdater.updateOptions(optionsData);
            UIUpdater.updateMessagesPanel(chatData);
            UIUpdater.updateMomentsData(momentsData);
            updateAppNotifications();
        }

        function handleDarkModeToggle() {
            const toggleBtn = $('#dark-mode-toggle');
            if (!toggleBtn) return;

            toggleBtn.addEventListener('click', function() {
                const isDark = document.documentElement.classList.toggle('dark');
                localStorage.setItem('tianxiang_theme_manual_override', 'true'); // User manually changed
                localStorage.setItem('tianxiang_theme', isDark ? 'dark' : 'light');
                toggleBtn.querySelector('i').className = isDark ? 'fas fa-sun' : 'fas fa-moon';
            });
        }

        function addRippleEffect() {
            document.addEventListener('click', function(e) {
                const target = e.target.closest('.menu-item, .choice-option, .reset-button, .moment-action, .moment-nav-button, .app-icon, .app-back-button, #back-to-list-btn, .detailed-view-action, .chat-input-action');
                if (!target || target.classList.contains('disabled') || target.disabled) return;

                const rect = target.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;

                const ripple = document.createElement('span');
                ripple.className = 'ripple-effect';
                ripple.style.cssText = `
                    position: absolute;
                    top: ${y}px;
                    left: ${x}px;
                    transform: translate(-50%, -50%);
                    width: 0;
                    height: 0;
                    background: rgba(var(--primary-color-rgb, 142, 108, 85), 0.3); /* Use primary color for ripple */
                    border-radius: 50%;
                    pointer-events: none;
                    z-index: 10; /* Ensure ripple is above other content but below text/icons */
                    animation: ripple 0.6s linear;
                `;

                // Ensure target has relative positioning if not already set, and overflow hidden
                const currentPosition = window.getComputedStyle(target).position;
                if (currentPosition === 'static') {
                    target.style.position = 'relative';
                }
                target.style.overflow = 'hidden';
                target.appendChild(ripple);

                setTimeout(() => {
                    ripple.remove();
                }, 600);
            });

            const style = document.createElement('style');
            style.textContent = `
                @keyframes ripple {
                    0% { width: 0; height: 0; opacity: 0.7; }
                    100% { width: 300px; height: 300px; opacity: 0; }
                }
                .dark .ripple-effect {
                    background: rgba(var(--dark-primary-color-rgb, 219, 180, 138), 0.3);
                }
            `;
            document.head.appendChild(style);
        }

        function init() {
            checkDarkMode(); // Check system/localStorage preference first
            const savedSettings = loadSettings();
            UIUpdater.loadSettingsToPanel(savedSettings); // Apply loaded settings

            handlePanelSwitching(); 
            handleSettingsChanges();
            handlePlayerChoiceClick();
            handleMomentsInteractions();
            handleDarkModeToggle(); // Then setup the toggle button
            handleMomentNavigation();
            addRippleEffect();

            updatePhoneTime();
            setInterval(updatePhoneTime, 60000); 

            handleAppIconClicks();
            handlePhoneAppBackButtons(); // This now includes the detailed message back button setup

            document.body.addEventListener('click', handleGlobalMediaClick);

            const viewer = $('.media-viewer');
            const closeBtn = viewer ? viewer.querySelector('.viewer-close') : null;
            if (closeBtn) closeBtn.addEventListener('click', () => viewer.classList.remove('active'));
            if (viewer) viewer.addEventListener('click', (e) => { if (e.target === viewer) viewer.classList.remove('active'); });
            document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && viewer && viewer.classList.contains('active')) { viewer.classList.remove('active'); } });

            const dataContainer = $('#injected-data-container');
            if (dataContainer) {
                const injectedRawData = dataContainer.textContent || "";
                processInjectedText(injectedRawData);
            } else {
                // Initialize with empty data if no injected data
                UIUpdater.updateMainContent(null); 
                UIUpdater.updateOptions([]); 
                UIUpdater.updateMessagesPanel([]); 
                UIUpdater.updateMomentsData([]);
            }
            // Ensure initial notifications are correct
            updateAppNotifications();
        }
        document.addEventListener('DOMContentLoaded', init);
    })();
    </script>
</body>
</html>
```

